import "fmt"

const Versao = "1.22"

func main() {
    var saldo int          // Zero value = 0
    ativo := true          // Inferência curta (bool)

    if ativo && saldo == 0 {
        fmt.Println("Conta nova na versão", Versao)
    }

    switch saldo {
    case 0:
        fmt.Println("Sem saldo")
    default:
        fmt.Println("Saldo disponível")
    }
}

